using Microsoft.AspNetCore.Identity; using Xunit; public class PasswordTests { [Fact] public void PasswordHasher_VerifiesCorrectPasswordAndRejectsWrongPassword() { var h = new PasswordHasher<string>(); var hash = h.HashPassword("user", "StrongPassword123!"); Assert.NotEqual("StrongPassword123!", hash); Assert.Equal(PasswordVerificationResult.Success, h.VerifyHashedPassword("user", hash, "StrongPassword123!")); Assert.Equal(PasswordVerificationResult.Failed, h.VerifyHashedPassword("user", hash, "wrong")); } }
